  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "街灯太亮 照不暖空房间"
        },
        {
          "id": "V1-02",
          "zh": "乙醚擦过皮肤 冷得没有痛"
        },
        {
          "id": "V1-03",
          "zh": "凌晨两点 睡意全无"
        },
        {
          "id": "V1-04",
          "zh": "一切都在急速地崩塌改变"
        },
        {
          "id": "V1-05",
          "zh": "油已用尽的打火机"
        },
        {
          "id": "V1-06",
          "zh": "胃里灼烧 像有火慢慢啃咬"
        },
        {
          "id": "V1-07",
          "zh": "如果这一切全都是假"
        },
        {
          "id": "V1-08",
          "zh": "那该多好 可惜都不是"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "霓虹挑染 街灯亮得发冷"
        },
        {
          "id": "V1-02",
          "zh": "乙醚的凉 顺着手背爬上肩"
        },
        {
          "id": "V1-03",
          "zh": "凌晨两点 我还没睡"
        },
        {
          "id": "V1-04",
          "zh": "一切都在 飞快地改变形状"
        },
        {
          "id": "V1-05",
          "zh": "打火机 擦不出火星"
        },
        {
          "id": "V1-06",
          "zh": "胃里在烧 像贴住一块烙铁"
        },
        {
          "id": "V1-07",
          "zh": "若这一切 全都是假的"
        },
        {
          "id": "V1-08",
          "zh": "那该多好 真的该多好"
        }
      ]
    }
  ]
}

